import json, os
BASE="/home/hatch/workspace/divination/benchmark/phase3/runs/round78/predictions"
os.makedirs(BASE, exist_ok=True)
def T(cm=False, ru=False, di=False, reason=""):
    return {"changed_main":cm,"reserve_used":ru,"disputed":di,"reason":reason}
P={}
def add(cid, text, basis, conf, trig):
    P[cid]={"case_id":cid,"prediction_text":text,"basis":basis,"confidence":conf,"trigger":trig}

